const int n = std::static_cast<int>(positions.size());
forces.assign(n, std::vec3(0.0));

for (int i = 0; i < n; ++i) {
    const auto& pos_i = positions[i];
    for (int j = i + 1; j < n; ++j) {
        const auto& pos_j = positions[j];

        // Calculate minimum image distance with periodic boundary conditions
        std::vec3 dx = pos_j - pos_i;
        dx.x() = std::min(std::abs(dx.x()), boxSize - std::abs(dx.x()));
        dx.y() = std::min(std::abs(dx.y()), boxSize - std::abs(dx.y()));
        dx.z() = std::min(std::abs(dx.z()), boxSize - std::abs(dx.z()));
        dx = (dx.x() < boxSize/2.0 ? dx : (dx.x() > 0 ? dx - std::vec3(boxSize, 0.0, 0.0) : dx + std::vec3(boxSize, 0.0, 0.0)));
        dx = (dx.y() < boxSize/2.0 ? dx : (dx.y() > 0 ? dx - std::vec3(0.0, boxSize, 0.0) : dx + std::vec3(0.0, boxSize, 0.0)));
        dx = (dx.z() < boxSize/2.0 ? dx : (dx.z() > 0 ? dx - std::vec3(0.0, 0.0, boxSize) : dx + std::vec3(0.0, 0.0, boxSize)));

        const double r_sq = dx.squaredLength();
        const double r = std::sqrt(r_sq);

        // Check cutoff condition
        if (r < cutoffRadius) {
            const double r6 = r_sq * r_sq * r_sq;
            const double r12 = r6 * r6;
            const double force_magnitude = 24.0 * epsilon * (2.0 * r12 / r_sq - r6 / r) / r;

            // Apply force to both particles (Newton's third law)
            const std::vec3 force_vec = force_magnitude * dx / r;
            forces[i] -= force_vec;
            forces[j] += force_vec;
        }
    }
}
// END_CODE

